<script setup lang="ts">
import{computed,onMounted,reactive,ref,watch}from'vue'
import{useRoute,useRouter}from'vue-router'
import{ElMessage,ElMessageBox}from'element-plus'
import{useAuthStore}from'../../stores/auth'
import type{Appointment,AppointmentSlot,Department,DoctorSummary}from'../../types/medical'
import{cancelAppointment,completeAppointment,createAppointment,getAppointments,getDepartments,getDoctors,getSlots,markNoShow,startAppointment}from'../../services/appointments'

const auth=useAuthStore(),route=useRoute(),router=useRouter(),loading=ref(false),appointments=ref<Appointment[]>([]),total=ref(0),page=ref(1),status=ref('')
const bookingOpen=ref(false),booking=reactive({department:undefined as number|undefined,doctor:undefined as number|undefined,date:'',slot:undefined as number|undefined,reason:''})
const departments=ref<Department[]>([]),doctors=ref<DoctorSummary[]>([]),slots=ref<AppointmentSlot[]>([]),submitting=ref(false)
const isPatient=computed(()=>auth.user?.role==='patient'),isDoctor=computed(()=>auth.user?.role==='doctor')
const title=computed(()=>isPatient.value?'预约挂号':isDoctor.value?'接诊管理':'预约管理')
const description=computed(()=>isPatient.value?'选择科室、医师和可用号源，管理个人预约':isDoctor.value?'按规范状态推进本人负责的预约':'查看全院预约并监督业务状态')
const statusMap:Record<string,{label:string;type:''|'success'|'warning'|'danger'|'info'}>={pending:{label:'待就诊',type:'warning'},in_progress:{label:'就诊中',type:''},completed:{label:'已完成',type:'success'},cancelled:{label:'已取消',type:'info'},no_show:{label:'爽约',type:'danger'}}
const minDate=new Date().toISOString().slice(0,10)

async function load(){loading.value=true;try{const result=await getAppointments({page:page.value,status:status.value||undefined});appointments.value=result.rows;total.value=result.count}catch{appointments.value=[];total.value=0}finally{loading.value=false}}
async function openBooking(){bookingOpen.value=true;if(!departments.value.length)try{departments.value=await getDepartments();const department=Number(route.query.department),doctor=Number(route.query.doctor);if(department){booking.department=department;await selectDepartment()}if(doctor)booking.doctor=doctor}catch{ElMessage.error('科室数据加载失败')}}
async function selectDepartment(){booking.doctor=undefined;booking.slot=undefined;slots.value=[];try{doctors.value=booking.department?await getDoctors(booking.department):[]}catch{doctors.value=[]}}
async function selectSchedule(){booking.slot=undefined;if(!booking.doctor||!booking.date){slots.value=[];return}try{slots.value=await getSlots(booking.doctor,booking.date)}catch{slots.value=[];ElMessage.error('号源加载失败')}}
async function submitBooking(){if(!booking.slot){ElMessage.warning('请选择预约号源');return}if(!booking.reason.trim()){ElMessage.warning('请填写就诊原因');return}submitting.value=true;try{await createAppointment({slot_id:booking.slot,reason:booking.reason.trim()});ElMessage.success('预约成功');bookingOpen.value=false;Object.assign(booking,{department:undefined,doctor:undefined,date:'',slot:undefined,reason:''});await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'预约失败，请重新选择号源')}finally{submitting.value=false}}
async function action(row:Appointment,kind:'cancel'|'start'|'complete'|'no-show'){const wording={cancel:'取消预约',start:'开始接诊',complete:'完成诊疗','no-show':'标记爽约'}[kind];try{await ElMessageBox.confirm(`确定要${wording}吗？`,wording,{type:kind==='cancel'||kind==='no-show'?'warning':'info'});const fn={cancel:cancelAppointment,start:startAppointment,complete:completeAppointment,'no-show':markNoShow}[kind];await fn(row.id);ElMessage.success('状态已更新');if(kind==='start'){await router.push(`/doctor/visits/${row.id}`);return}await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.detail||'操作失败')}}
watch(status,()=>{page.value=1;load()});onMounted(async()=>{await load();if(isPatient.value&&(route.query.doctor||route.query.department))await openBooking()})
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">APPOINTMENT WORKFLOW</p><h1>{{title}}</h1><p>{{description}}</p></div><el-button v-if="isPatient" type="primary" @click="openBooking">＋ 预约挂号</el-button></div><el-card class="table-card"><div class="table-tools"><el-select v-model="status" clearable placeholder="全部状态" style="width:160px"><el-option v-for="(value,key) in statusMap" :key="key" :label="value.label" :value="key"/></el-select><span class="workflow-hint">待就诊 → 就诊中 → 已完成</span></div><el-table v-loading="loading" :data="appointments" empty-text="暂无预约记录"><el-table-column prop="appointment_no" label="预约编号" min-width="145"/><el-table-column v-if="!isPatient" prop="patient_name" label="患者" min-width="110"/><el-table-column v-if="!isDoctor" prop="doctor_name" label="医师" min-width="110"/><el-table-column prop="department_name" label="科室" min-width="110"/><el-table-column label="就诊时间" min-width="180"><template #default="{row}">{{row.slot?.date}} {{row.slot?.start_time?.slice(0,5)}}–{{row.slot?.end_time?.slice(0,5)}}</template></el-table-column><el-table-column prop="reason" label="就诊原因" min-width="180" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="statusMap[row.status]?.type||'info'">{{statusMap[row.status]?.label||row.status}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="170" fixed="right"><template #default="{row}"><el-button v-if="isPatient&&row.status==='pending'" link type="danger" @click="action(row,'cancel')">取消</el-button><template v-if="isDoctor"><el-button v-if="row.status==='pending'" link type="primary" @click="action(row,'start')">接诊</el-button><el-button v-if="row.status==='pending'" link type="danger" @click="action(row,'no-show')">爽约</el-button><el-button v-if="row.status==='in_progress'" link type="success" @click="action(row,'complete')">完成诊疗</el-button></template></template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page" layout="prev,pager,next" :total="total" @change="load"/></div></el-card><el-dialog v-model="bookingOpen" title="预约挂号" width="min(560px,94vw)" destroy-on-close><el-form label-position="top"><el-row :gutter="14"><el-col :span="12"><el-form-item label="科室"><el-select v-model="booking.department" placeholder="选择科室" style="width:100%" @change="selectDepartment"><el-option v-for="item in departments" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="医师"><el-select v-model="booking.doctor" placeholder="选择医师" style="width:100%" :disabled="!booking.department" @change="selectSchedule"><el-option v-for="item in doctors" :key="item.id" :label="`${item.full_name} · ${item.title}`" :value="item.id"/></el-select></el-form-item></el-col></el-row><el-form-item label="预约日期"><el-date-picker v-model="booking.date" type="date" value-format="YYYY-MM-DD" :disabled-date="(date:Date)=>date.getTime()<new Date(minDate).setHours(0,0,0,0)" style="width:100%" :disabled="!booking.doctor" @change="selectSchedule"/></el-form-item><el-form-item label="可用号源"><div v-if="slots.length" class="slot-list"><button v-for="item in slots" :key="item.id" type="button" :class="{selected:booking.slot===item.id}" @click="booking.slot=item.id">{{item.start_time.slice(0,5)}}–{{item.end_time.slice(0,5)}}</button></div><el-empty v-else :image-size="60" description="请选择医师和日期查看号源"/></el-form-item><el-form-item label="就诊原因"><el-input v-model="booking.reason" type="textarea" :rows="3" maxlength="300" show-word-limit placeholder="请简要描述症状或就诊需求"/></el-form-item></el-form><template #footer><el-button @click="bookingOpen=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submitBooking">确认预约</el-button></template></el-dialog></section></template>
